local OverseaClubBossRankNode = Class('OverseaClubBossRankNode')
function OverseaClubBossRankNode:__init()
    self.checkCb = nil
end

function OverseaClubBossRankNode:__delete()
    self.checkCb = nil
end

function OverseaClubBossRankNode:SetCheckCallBack(callBack)
    self.checkCb = callBack
end

function OverseaClubBossRankNode:Awake()
    if self.BtnCheck then
        SetButtonAction(self.BtnCheck.gameObject,Bind(self,self.OnBtnCheckClick))
    end
end

function OverseaClubBossRankNode:Refresh(data,isLast)
    local hasRank = data.rank ~= 0
    KTool.SetActive(self.Layout.gameObject,hasRank)
    KTool.SetActive(self.Empty.gameObject,not hasRank)

    if hasRank then
        CfUtils.FillText(self.TextNumber.gameObject,data.rank)
    end

    CfUtils.FillImage(self.ImgHead.gameObject,data.photoPath)

    if not isNull(self.TextTitle) then
        local status = isLast and 2 or 1
        CfUtils.SetUISwitchText(self.TextTitle,status)
    end

    if self.BtnCheck then
        KTool.SetActive(self.BtnCheck.gameObject,not isLast)
    end
end

function OverseaClubBossRankNode:OnBtnCheckClick()
    if not isNull(self.checkCb) then
        self.checkCb()
    end
end

function OverseaClubBossRankNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaClubBossRankNode